write_qr_with_logo <- function(url, outfile, logo_path = "assets/logo/logo-small.png") {
  qr <- qrencoder::qrencode(url)
  n <- nrow(qr)
  png::writePNG(array(1, dim = c(10, 10, 4)), tempfile(fileext = ".png"))
  png(outfile, width = 1200, height = 1200, bg = "white", res = 160)
  par(mar = c(0, 0, 0, 0), xaxs = "i", yaxs = "i")
  plot(c(0, n), c(0, n), type = "n", axes = FALSE, xlab = "", ylab = "", asp = 1)
  # draw modules. TRUE values are dark in qrencoder matrix.
  for (i in seq_len(n)) {
    for (j in seq_len(n)) {
      col <- if (isTRUE(qr[i, j])) "black" else "white"
      rect(j - 1, n - i, j, n - i + 1, col = col, border = NA)
    }
  }
  # White center backing + logo overlay
  rect(n * 0.36, n * 0.36, n * 0.64, n * 0.64, col = "white", border = "#005b9e", lwd = 3)
  if (file.exists(logo_path)) {
    lg <- png::readPNG(logo_path)
    rasterImage(lg, n * 0.385, n * 0.385, n * 0.615, n * 0.615, interpolate = TRUE)
  }
  dev.off()
}

for (i in seq_len(nrow(qr_entries))) {
  write_qr_with_logo(qr_entries$url[i], file.path("qr", paste0(qr_entries$slug[i], ".png")))
}
