# Render Quarto website
message("Rendering Quarto website...")
q <- Sys.which("quarto")
if (nzchar(q)) {
  status <- system2(q, "render")
} else if (requireNamespace("quarto", quietly = TRUE)) {
  quarto::quarto_render(input = ".")
  status <- 0
} else {
  stop("Quarto CLI not found. Install Quarto, then run this script again.")
}
if (!identical(status, 0L) && !identical(status, 0)) stop("Quarto render failed.")
file.create("docs/.nojekyll")
